def inside(x, y, poly):
    hit = False
    j = len(poly) - 1
    for i, (xi, yi) in enumerate(poly):
        xj, yj = poly[j]
        crosses = ((yi > y) != (yj > y))
        if crosses:
            at_x = (xj - xi) * (y - yi) / (yj - yi) + xi
            if x < at_x:
                hit = not hit
        j = i
    return hit

def land(x, y):
    return any(inside(x, y, p) for p in polygons)

def main():
    rows = []
    for r in range(64):
        lat = 35.0 - (2.0 / 63.0) * r
        row = []
        for c in range(253):
            lon = 129.0 + (2.0 / 63.0) * c
            row.append(1 if land(lon, lat) else 0)
        rows.append(row)

    out = Path('outputs')
    out.mkdir(parents=True, exist_ok=True)
    with (out / 'candidate.csv').open('w', newline='', encoding='ascii') as f:
        csv.writer(f, lineterminator='\n').writerows(rows)

    # Pillow's one-bit image gives exactly black and white pixels.
    img = Image.new('1', (253, 64))
    pix = img.load()
    for y, row in enumerate(rows):
        for x, value in enumerate(row):
            pix[x, y] = 1 if value else 0
    img.save(out / 'candidate.png')
    big = img.resize((2024, 512), Image.Resampling.NEAREST)
    big.save(out / 'candidate_8x.png')

    assert len(rows) == 64 and all(len(row) == 253 for row in rows)
    assert all(value in (0, 1) for row in rows for value in row)
    assert img.size == (253, 64) and big.size == (2024, 512)

if __name__ == '__main__':
    main()
